fn apply(f: fn(Int64, Int64) -> Int64, a: Int64, b: Int64) -> Int64 {
    return f(a, b)
}

fn f() -> Int64 {
    let pick = |a: Int64, b: Int64| if a > b { a } else { b }
    let rank = |n: Int64| match n {
        0 => 10
        _ => 20
    }
    let sum: fn(Int64, Int64) -> Int64 = |a, b| { if a > b { a } else { b } }
    return apply(pick, 1, 2) + rank(0) + apply(sum, 3, 4)
}

